/// Arriving: starts fast, settles.
pub const MOTION_EASING_ENTER: CubicBezier = [0.0, 0.0, 0.0, 1.0];
/// Leaving: starts slow, gets out of the way.
pub const MOTION_EASING_EXIT: CubicBezier = [0.3, 0.0, 1.0, 1.0];

