/// Control sizes, for one input device.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Sizes {
    pub control_sm: f32,
    pub control_md: f32,
    pub control_lg: f32,
    /// The smallest area that reacts to a press, whatever the control looks like.
    pub target_min: f32,
    pub switch_width: f32,
    pub switch_height: f32,
    /// The box, not the pressable area.
    pub checkbox: f32,
    /// The least height of a row in a list.
    pub list_row: f32,
    /// Top bars and tab bars.
    pub bar: f32,
    /// Buttons are rounded rectangles where a pointer is used.
    pub button_radius: f32,
    pub icon_sm: f32,
    /// Icons beside text.
    pub icon_md: f32,
    /// Icons that stand alone: tab bars, top bars.
    pub icon_lg: f32,
    pub avatar_sm: f32,
    pub avatar_md: f32,
    pub avatar_lg: f32,
    /// The height of a badge.
    pub badge: f32,
    /// The thickness of a progress bar.
    pub progress: f32,
    pub spinner_sm: f32,
    pub spinner_md: f32,
    pub spinner_lg: f32,
}

